/* Standalone mixer decode test - runs under node via emcc build.
 * Links only src/web/psx/mixer.c; VAG + expected PCM from
 * .tmp_test/vag_ss3.h (generated by tools/vag_decode.py).
 *
 * Pitch 0x1000 = 44100 Hz: output sample k should equal decoded
 * sample k once the ADSR envelope is full (we key with instant
 * attack/sustain-max and skip a settle margin).
 */
#include <math.h>
#include <stdio.h>
#include <stdint.h>
#include "../psx/mixer.h"
#include "../../../.tmp_test/vag_ss3.h"

#define VADDR 0x1010

static int16_t out[60000];

int main(void)
{
	int i, fails = 0;
	int n = (int)(sizeof(vag_test_pcm) / sizeof(vag_test_pcm[0]));

	mix_reset();
	mix_mem_write(VADDR, vag_test_bytes, sizeof(vag_test_bytes));

	/* voice 0: vol full, pitch 1:1, instant attack, sustain max */
	mix_voice_volume(0, 0x7FFF, 0x7FFF);
	mix_voice_pitch(0, 0x1000);
	mix_voice_sample(0, VADDR);
	mix_voice_adsr(0, 0x00FF, 0x0000); /* ar max, lin, sl=0xF; sr hold */
	mix_master_volume(0x7FFF, 0x7FFF);
	mix_key_on(1);

	if (n > 29500) n = 29500;
	mix_render(out, n + 200);

	/* pitch 0x1000: env ramp shifts alignment slightly; find
	 * best small offset then compare */
	{
		int bestoff = 0, besterr = 1 << 30;
		int o;
		for (o = -4; o <= 4; o++) {
			long e = 0;
			for (i = 100; i < 200; i++) {
				long d = out[(i + o) * 2] - vag_test_pcm[i];
				e += d < 0 ? -d : d;
			}
			if (e < besterr) { besterr = e; bestoff = o; }
		}
		for (i = 96; i < 112; i++)
			printf("i=%d out=%d exp=%d\n", i, out[(i+bestoff)*2],
			       vag_test_pcm[i]);
		{
			int maxd = 0, firstbad = -1;
			long so = 0, se = 0, sd = 0;
			for (i = 64; i < n; i++) {
				int d = out[(i + bestoff) * 2] - vag_test_pcm[i];
				if (d < 0) d = -d;
				if (d > maxd) maxd = d;
				if (d > 900 && firstbad < 0) firstbad = i;
				so += out[(i+bestoff)*2] < 0 ? -out[(i+bestoff)*2] : out[(i+bestoff)*2];
				se += vag_test_pcm[i] < 0 ? -vag_test_pcm[i] : vag_test_pcm[i];
				sd += d;
			}
			printf("pitch 0x1000: offset=%d maxdiff=%d firstbad=%d "
			       "sum|out|=%ld sum|exp|=%ld ratio=%.4f avgdiff=%ld\n",
			       bestoff, maxd, firstbad, so, se,
			       (double)so / se, sd / (n - 64));
			if (sd / (n - 64) > 1500) fails++;
			if ((double)so / se < 0.7 || (double)so / se > 1.1)
				fails++;
		}
	}

	/* half-speed check at pitch 0x0800 */
	mix_reset();
	mix_mem_write(VADDR, vag_test_bytes, sizeof(vag_test_bytes));
	mix_voice_volume(0, 0x7FFF, 0x7FFF);
	mix_voice_sample(0, VADDR);
	mix_voice_adsr(0, 0x00FF, 0x0000);
	mix_master_volume(0x7FFF, 0x7FFF);
	{
		int16_t o2[60000];
		mix_render(o2, 64);
		mix_voice_pitch(0, 0x0800);
		mix_key_on(1);
		mix_render(o2, 22000);
		{
			int k, mx=0;
			for (k=0;k<22000;k++) { int a=o2[k*2]; if (a<0)a=-a; if (a>mx)mx=a; }
			printf("o2 max=%d\n", mx);
		}
		/* output[i] ~ pcm[(i-lag)/2]; scan lag for best fit */
		{
			int bl = 0; long be = 1L << 40;
			int lag;
			for (lag = 0; lag < 32; lag += 2) {
				long e = 0;
				for (i = 400; i < 4000; i += 4) {
					long d = o2[i * 2] - vag_test_pcm[(i - lag) / 2];
					e += d < 0 ? -d : d;
				}
				if (e < be) { be = e; bl = lag; }
			}
			printf("pitch 0x0800: lag=%d avgdiff=%ld\n",
			       bl, be / 900);
			if (be / 900 > 6000) fails++;
		}
	}

	/* reverb impulse response (STUDIO_B, the preset the game uses):
	 * a 50 ms burst on a reverb-send voice must leave a tail that
	 * decays instead of ringing up or cutting off */
	{
		static int16_t ir[44100 * 3 * 2];
		double e[6] = {0};
		int k;
		mix_reset();
		mix_mem_write(VADDR, vag_test_bytes, sizeof(vag_test_bytes));
		mix_voice_volume(0, 0x3FFF, 0x3FFF);
		mix_voice_pitch(0, 0x1000);
		mix_voice_sample(0, VADDR);
		mix_voice_adsr(0, 0x00FF, 0x0000); /* release shift 0: instant */
		mix_master_volume(0x3FFF, 0x3FFF);
		mix_reverb_mode(3);
		mix_reverb_depth(0x7000, 0x7000);
		mix_reverb_voices(1);
		mix_reverb_enable(1);
		mix_key_on(1);
		mix_render(ir, 2205);
		mix_key_off(1);
		mix_render(ir, 44100 * 3);
		for (k = 0; k < 44100 * 3; k++) {
			double v = ir[k * 2];
			e[k / 22050] += v * v;
		}
		for (k = 0; k < 6; k++) {
			e[k] = sqrt(e[k] / 22050);
			printf("reverb tail %d.%ds rms=%.1f\n", k / 2, (k & 1) * 5, e[k]);
		}
		if (!(e[0] > 10 && e[1] < e[0] && e[3] < e[1] && e[5] < 0.5 * e[0]))
			fails++;
	}

	printf(fails ? "mixer_test: FAIL %d\n" : "mixer_test: pass\n", fails);
	return fails;
}
